package com.neosoft.neoflow.validation;

import static org.assertj.core.api.Assertions.assertThat;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

import java.time.Clock;
import java.time.Instant;
import java.time.LocalDate;
import java.time.ZoneId;
import java.util.Optional;

import org.junit.jupiter.api.Test;

import com.neosoft.neoflow.collaborateur.Collaborateur;
import com.neosoft.neoflow.collaborateur.CollaborateurRepository;
import com.neosoft.neoflow.demande.Demande;
import com.neosoft.neoflow.demande.TypeDemande;
import com.neosoft.neoflow.legacy.RegleValidationLegacy;

class CircuitValidationServiceSansMontantIaTest {

    @Test
    void demandeGeneriqueSansMontant_obtientLeNiveau1() {
        CircuitValidationService circuit = new CircuitValidationService(mock(CollaborateurRepository.class), Clock.fixed(Instant.parse("2026-11-04T09:00:00Z"), ZoneId.of("Europe/Paris")));
        Demande d = new Demande();
        d.setType(TypeDemande.GENERIQUE);
        d.setMontant(null);
        d.setUrgent(false);
        d.setDepartement("RH");

        assertThat(circuit.calculerNiveau(d, 24)).isEqualTo(1);
    }
}

