import com.neosoft.neoflow.demande.TypeDemande;
import com.neosoft.neoflow.legacy.RegleValidationLegacy;

class CircuitValidationServiceAncienneteIaTest {

    @Test
    void ancienneteMois_compteLesMoisRevolus() {
        CollaborateurRepository collaborateurs = mock(CollaborateurRepository.class);
        when(collaborateurs.findById("alice")).thenReturn(Optional.of(new Collaborateur("alice", "Alice Martin", "RH", LocalDate.of(2024, 11, 4))));
        CircuitValidationService circuit = new CircuitValidationService(collaborateurs, Clock.fixed(Instant.parse("2026-11-04T09:00:00Z"), ZoneId.of("Europe/Paris")));

        assertThat(circuit.ancienneteMois("alice")).isEqualTo(24);
    }
}

